      <div class="text--_30"><span class="fspan_54">기본기가 탄탄한 발표입니다<br/>한두 가지 디테일만 조금 더 다듬으면 훨씬 좋아질 거예요! 👏</span></div>
      <div class="ai-"><span class="ai_span">AI 인사이트</span></div>
      <div class="frame-2087331558_06">
        <div><span class="f01_span_16">맞춤 훈련 시작</span></div>
        <div class="frame-2087331633_02">
          <div class="vector_19"></div>
        </div>
      </div>
      <div class="text--_31"><span class="fspan_55">다음 발표에서는 전문 용어를 한 번 더 쉬운 말로 풀고, 결론 전 잠시 멈춰 핵심 메시지를 강조해보세요</span></div>
