      <div class="text-3000"><span class="f000_span_03">30:00</span></div>
      <div class="vector-28838"></div>
      <div class="vector-28839"></div>
      <div class="vector-28843"></div>
      <div class="vector-28840"></div>
      <div class="vector-28842"></div>
      <div class="frame-2087331640_01">
        <div class="bounding-box_48"></div>
        <div class="frame-2087331630_09">
          <div class="text--_32"><span class="fspan_56">시선이 집중되는 발표였어요</span></div>
          <div class="text--_33"><span class="fspan_57">핵심 구간에서 정면 응시가 길게 유지되었어요</span></div>
